// Equal dates use lexicographic IDs, independently of input order or tenant.
const rows = [
  { id: '2', tenant: 'a', createdAt: '2026-01-01', total: 2 },
  { id: '11', tenant: 'b', createdAt: '2026-01-01', total: 11 },
  { id: 'z', tenant: 'a', createdAt: '2026-01-02', total: 4 },
  { id: '10', tenant: 'a', createdAt: '2026-01-01', total: 10 },
  { id: '1', tenant: 'a', createdAt: '2026-01-01', total: 1 }
];
const snapshot = JSON.stringify(rows);
rows.forEach(Object.freeze);
Object.freeze(rows);
const paginated = new OrderHandler(new OrderRepository(rows));
let cursor;
const ids = [];
do {
  const page = paginated.list({ tenant: 'a', limit: 1, cursor });
  ids.push(...page.items.map(row => row.id));
  cursor = page.nextCursor;
} while (cursor !== null);
