assert.equal(JSON.stringify(rows), snapshot);
assert.deepEqual(paginated.list({ tenant: 'a', limit: 2 }), {
  items: [rows[4], rows[3]], nextCursor: '2026-01-01|10'
});
// Resume by pair, not by locating a row (foreign-tenant or deleted cursor).
for (const cursor of ['2026-01-01|11', '2026-01-01|12']) {
  assert.deepEqual(paginated.list({ tenant: 'a', limit: 1, cursor }), {
    items: [rows[0]], nextCursor: '2026-01-01|2'
  });
}
assert.deepEqual(paginated.list({ tenant: 'a', limit: 100, cursor: '2026-01-02|z' }), {
  items: [], nextCursor: null
});
assert.deepEqual(paginated.list({ tenant: 'missing', limit: 1 }), { items: [], nextCursor: null });
assert.equal(paginated.list({ tenant: 'a', limit: 4 }).nextCursor, null);
for (const cursor of ['', '|', 'date|', '|id', 'date|id|extra', null, 12]) {
  assert.throws(() => paginated.list({ tenant: 'a', limit: 1, cursor }), /^Error: invalid request$/);
}
for (const limit of [0, 101, 1.5, NaN, Infinity, '1']) {
